// The generator's renderers. Imports carry `.ts` so `node scripts/generate.ts` runs them unbundled;
// the package index does not export this file, so the apps never compile it.
import {
  type ColorRoleEntry,
  colorGroups,
  colorRoleNames,
  darkColors,
  lightColors,
} from './colors.ts';
import { springCurve, springs } from './motion.ts';
import { radii, spacing } from './shape.ts';
import { fontFaces, fontFamily, typeScale } from './type.ts';

const GENERATED =
  'Generated by @repo/design from packages/design/src (pnpm --filter @repo/design gen). Do not edit.';

const kebab = (name: string) => name.replace(/[A-Z]/g, (c) => `-${c.toLowerCase()}`);

function block(indent: string, groups: readonly string[][]) {
  return groups.map((lines) => lines.map((line) => `${indent}${line}\n`).join('')).join('\n');
}

function colorLines(theme: 'light' | 'dark', notes: boolean) {
  return (colorGroups as readonly (readonly ColorRoleEntry[])[]).map((group) =>
    group.flatMap(([name, light, dark, note]) => [
      ...(notes && note ? [`/* ${note} */`] : []),
      `--color-${name}: ${theme === 'light' ? light : dark};`,
    ]),
  );
}

const px = (values: Record<string, number>, prefix: string) =>
  Object.entries(values).map(([name, value]) => `--${prefix}-${name}: ${value}px;`);

/** apps/mobile/global.css: the Uniwind entry, with the tokens as `@theme` and `@variant` blocks. */
export function mobileGlobalCss() {
  const theme = [
    [
      '/* Funnel Display, one static file per weight (Android picks fonts by family). */',
      ...Object.entries(fontFaces).map(([name, face]) => `--font-${name}: ${face.expo};`),
    ],
    px(radii, 'radius'),
    px(spacing, 'spacing'),
  ];
  return `@import 'tailwindcss';
@import 'uniwind';

/* ${GENERATED} */

@theme {
${block('  ', theme)}}

@layer theme {
  :root {
    @variant light {
${block('      ', colorLines('light', true))}    }

    @variant dark {
${block('      ', colorLines('dark', false))}    }
  }
}
`;
}

/** apps/mobile/constants/theme-tokens.generated.ts: the colours for JS props through `useThemeTokens()`. */
export function mobileThemeTokensTs() {
  const key = (name: string) => (/^[a-z]\w*$/i.test(name) ? name : `'${name}'`);
  const map = (colors: Record<string, string>) =>
    colorRoleNames.map((name) => `  ${key(name)}: '${colors[name]}',`).join('\n');
  return `// ${GENERATED}

export const themeTokenNames = [
${colorRoleNames.map((name) => `  '${name}',`).join('\n')}
] as const;

export type ThemeTokenName = (typeof themeTokenNames)[number];

export const lightThemeTokens: Record<ThemeTokenName, string> = {
${map(lightColors)}
};

export const darkThemeTokens: Record<ThemeTokenName, string> = {
${map(darkColors)}
};
`;
}

/** packages/design/src/icons.generated.ts: every MDI name the phone app uses, from one pinned MDI version. */
export function iconNamesTs(names: readonly string[], mdiVersion: string) {
  return `// ${GENERATED}

/** The Material Design Icons release the phone's icon font ships. The web pins the same one. */
export const mdiVersion = '${mdiVersion}';

/**
 * Every string literal in apps/mobile and @repo/types that names an MDI glyph: each icon the phone
 * draws, and a few words that happen to be glyph names too.
 */
export const iconNames = [
${names.map((name) => `  '${name}',`).join('\n')}
] as const;

export type IconName = (typeof iconNames)[number];
`;
}

/**
 * packages/design/tokens.css: the same names as plain CSS variables for the web. Light on `:root`,
 * dark under `[data-theme='dark']` or the system setting unless `[data-theme='light']` pins light.
 * Type and motion follow Tailwind v4's theme namespaces (`--text-*`, `--ease-*`).
 */
export function webTokensCss() {
  const type = Object.entries(typeScale).map(([name, style]) => {
    const prefix = `--text-${kebab(name)}`;
    return [
      `${prefix}: ${style.size}px;`,
      `${prefix}--line-height: ${style.line}px;`,
      `${prefix}--letter-spacing: ${style.tracking}em;`,
      `${prefix}--font-weight: ${fontFaces[style.face].weight};`,
    ];
  });
  const motion = Object.entries(springs).map(([name, spring]) => {
    const curve = springCurve(spring);
    return [`--ease-${name}: ${curve.linear};`, `--duration-${name}: ${curve.durationMs}ms;`];
  });
  const root = [
    [
      'color-scheme: light;',
      `--font-display: '${fontFamily}', system-ui, sans-serif;`,
      ...Object.entries(fontFaces)
        .filter(([name]) => name !== 'display')
        .map(([name, face]) => `--font-weight-${name}: ${face.weight};`),
    ],
    px(radii, 'radius'),
    px(spacing, 'spacing'),
    type.flat(),
    motion.flat(),
    colorLines('light', false).flat(),
  ];
  const dark = [['color-scheme: dark;', ...colorLines('dark', false).flat()]];
  return `/* ${GENERATED} */

:root {
${block('  ', root)}}

[data-theme='dark'] {
${block('  ', dark)}}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme='light']) {
${block('    ', dark)}  }
}
`;
}
